  for (const corpus of ['mantine', 'chakra', 'shadcn', 'antd', 'spectrum']) {
    const d = JSON.parse(readFileSync(`${root}/${run}/work/${corpus}.oracle.json`, 'utf8'))
    const tally: Record<string, Record<string, number>> = {}
