import { readFileSync, writeFileSync } from 'node:fs'

const want: [string, string, string][] = [
  ['antd', 'Badge', 'color'],
  ['antd', 'Flex', 'gap'],
  ['antd', 'Col', 'flex'],
  ['antd', 'Input', 'type'],
  ['mantine', 'Avatar', 'color'],
  ['shadcn', 'BlockImage', 'placeholder'],
  ['shadcn', 'ThemeProvider', 'attribute'],
  ['shadcn', 'Form', 'watch'],
  ['shadcn', 'Form', 'getValues'],
  ['chakra', 'AbsoluteCenter', 'axis'],
]
const out: Record<string, unknown> = {}
for (const [corpus, component, prop] of want) {
  const d = JSON.parse(readFileSync(`/tmp/claude-501/oracle-rerun/B/work/${corpus}.oracle.json`, 'utf8'))
  const row = Object.values<any[]>(d.examples)
    .flat()
    .find((r) => r.component === component && r.prop === prop)
  if (!row) throw new Error(`missing ${component}.${prop}`)
  out[`${component}.${prop}`] = { corpus, verdictSaved: Object.entries<any[]>(d.examples).find(([, v]) => v.includes(row))![0], normalized: row.normalized }
}
writeFileSync(process.argv[2], JSON.stringify(out, null, 1) + '\n')

